use std::sync::Mutex;

static INNER: Mutex<i32> = Mutex::new(1);

pub fn static_alias(outer: &mut i32) -> bool {
    let mut inner = INNER.lock().unwrap();
    if *outer >= *inner {
        *inner = inner.wrapping_add(*outer);
        true
    } else {
        *outer = outer.wrapping_add(*inner);
        false
    }
}

pub fn driver(initial_value: i32, iterations: i32) {
    let mut local_outer = initial_value;
    let mut is_static = false;

    for _i in 0..iterations {
        if is_static {
            let mut inner = INNER.lock().unwrap();
            if local_outer >= *inner {
                *inner = inner.wrapping_add(local_outer);
            } else {
                local_outer = local_outer.wrapping_add(*inner);
                is_static = false;
            }
            output_i32(*inner);
        } else {
            if local_outer >= {
                let inner = INNER.lock().unwrap();
                *inner
            } {
                let mut inner = INNER.lock().unwrap();
                *inner = inner.wrapping_add(local_outer);
                is_static = true;
                output_i32(*inner);
            } else {
                let inner = INNER.lock().unwrap();
                local_outer = local_outer.wrapping_add(*inner);
                output_i32(local_outer);
            }
        }
        crate::ffi::put_byte(b'\n');
    }
}

fn output_i32(val: i32) {
    if val < 0 {
        crate::ffi::put_byte(b'-');
        output_u32((val.wrapping_neg()) as u32);
    } else {
        output_u32(val as u32);
    }
}

fn output_u32(mut val: u32) {
    if val == 0 {
        crate::ffi::put_byte(b'0');
        return;
    }

    let mut digits = [0u8; 10];
    let mut count = 0;
    while val > 0 {
        digits[count] = (val % 10) as u8 + b'0';
        val /= 10;
        count += 1;
    }

    for i in (0..count).rev() {
        crate::ffi::put_byte(digits[i]);
    }
}
